 * The result envelope every Server Action and Route Handler returns. Actions
 * never throw for expected failures — they return `ActionResult` so the client
 * form layer can render field errors without an error boundary.
 */

export type ErrorCode =
  | "unauthorized"
  | "forbidden"
  | "not_found"
  | "validation_failed"
  | "conflict"
  | "rate_limited"
  | "plan_limit_exceeded"
  | "tenant_scope_violation"
  | "internal_error";

export interface AppErrorShape {
  readonly code: ErrorCode;
  readonly message: string;
  /** Zod-style field path → messages, for react-hook-form to consume. */
  readonly fieldErrors?: Readonly<Record<string, readonly string[]>>;
  readonly meta?: Readonly<Record<string, string | number | boolean>>;
}

export type Result<T, E = AppErrorShape> =
  | { readonly ok: true; readonly data: T }
  | { readonly ok: false; readonly error: E };

/** What a Server Action returns to a `useActionState` reducer. */
export type ActionResult<T> = Result<T> & {
  /** Monotonic token so the client can distinguish two identical results. */
  readonly submittedAt?: string;
};

export interface ApiErrorBody {
  readonly error: AppErrorShape;
}

export function ok<T>(data: T): Result<T> {
  return { ok: true, data };
}

export function err<T = never>(error: AppErrorShape): Result<T> {
  return { ok: false, error };
}

export function isOk<T, E>(
  result: Result<T, E>,
): result is { ok: true; data: T } {
  return result.ok;
}
import { and, eq, gt, isNull, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, members, organizations, ownershipHandovers } from "@/server/db";
import { toIsoTimestamp, type IsoTimestamp, type OrgId, type UserId } from "@/types/common";
import type { OwnershipHandover, OwnershipHandoverStatus } from "@/types/organization";
import { brandId, brandStamp, brandStampOrNull, toMember, toOrganization } from "./_mappers";
import type { Member } from "@/types/member";
import type { Organization } from "@/types/organization";

function map(row: typeof ownershipHandovers.$inferSelect): OwnershipHandover {
  return {
    id: row.id,
    orgId: brandId<OrgId>(row.orgId),
    fromUserId: brandId<UserId>(row.fromUserId),
    toUserId: brandId<UserId>(row.toUserId),
    status: row.status,
    expiresAt: brandStamp(row.expiresAt),
    createdAt: brandStamp(row.createdAt),
    resolvedAt: brandStampOrNull(row.resolvedAt),
  };
}

export async function findPending(orgId: OrgId, now: IsoTimestamp): Promise<OwnershipHandover | null> {
  const db = getDb();
  const row = db.select().from(ownershipHandovers)
    .where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending")))
    .get();
  if (!row) return null;
  if (row.expiresAt <= now) {
    db.update(ownershipHandovers)
      .set({ status: "expired", resolvedAt: row.expiresAt })
      .where(and(eq(ownershipHandovers.id, row.id), eq(ownershipHandovers.status, "pending")))
      .run();
    return null;
  }
  return map(row);
}

/** Returns an expired row too, so the invited recipient gets the precise lapse refusal. */
export async function findPendingForAction(orgId: OrgId, now: IsoTimestamp): Promise<OwnershipHandover | null> {
  const db = getDb();
  const row = db.select().from(ownershipHandovers)
    .where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending")))
    .get();
  if (!row) return null;
  if (row.expiresAt <= now) {
    const expired = db.update(ownershipHandovers)
      .set({ status: "expired", resolvedAt: row.expiresAt })
      .where(and(eq(ownershipHandovers.id, row.id), eq(ownershipHandovers.status, "pending")))
      .returning().get();
    return expired ? map(expired) : null;
  }
  return map(row);
}

export async function findPendingForRecipient(
  orgId: OrgId,
  recipientId: UserId,
  now: IsoTimestamp,
): Promise<OwnershipHandover | null> {
  const current = await findPendingForAction(orgId, now);
  if (current?.toUserId === recipientId || (current && current.status === "expired" && current.toUserId === recipientId)) return current;
  const expired = getDb().select().from(ownershipHandovers)
    .where(and(
      eq(ownershipHandovers.orgId, orgId),
      eq(ownershipHandovers.toUserId, recipientId),
    ))
    .orderBy(sql`${ownershipHandovers.createdAt} DESC`).get();
  return expired?.status === "expired" ? map(expired) : current;
}

export async function create(
  orgId: OrgId,
  fromUserId: UserId,
  toUserId: UserId,
  createdAt: IsoTimestamp,
): Promise<OwnershipHandover | null> {
  const expiresAt = toIsoTimestamp(new Date(new Date(createdAt).getTime() + 7 * 24 * 60 * 60 * 1000));
  const row = getDb().transaction((tx) => {
    const existing = tx.select().from(ownershipHandovers)
      .where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending"))).get();
    if (existing && existing.expiresAt > createdAt) return null;
    if (existing) {
      tx.update(ownershipHandovers).set({ status: "expired", resolvedAt: existing.expiresAt })
        .where(and(eq(ownershipHandovers.id, existing.id), eq(ownershipHandovers.status, "pending"))).run();
    }
    return tx.insert(ownershipHandovers).values({
      id: newId(), orgId, fromUserId, toUserId, status: "pending", expiresAt, createdAt, resolvedAt: null,
    }).returning().get();
  });
  return row ? map(row) : null;
}

export async function resolve(
  handover: OwnershipHandover,
  status: Exclude<OwnershipHandoverStatus, "pending">,
  at: IsoTimestamp,
): Promise<OwnershipHandover> {
  const row = getDb().update(ownershipHandovers)
    .set({ status, resolvedAt: at })
    .where(and(eq(ownershipHandovers.id, handover.id), eq(ownershipHandovers.status, "pending")))
    .returning().get();
  if (!row) throw new Error("Ownership handover is no longer pending");
  return map(row);
}

export async function cancelOpenForMember(orgId: OrgId, userId: UserId, at: IsoTimestamp): Promise<void> {
  getDb().update(ownershipHandovers)
    .set({ status: "expired", resolvedAt: sql`${ownershipHandovers.expiresAt}` })
    .where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending"), sql`${ownershipHandovers.expiresAt} <= ${at}`)).run();
  getDb().update(ownershipHandovers)
    .set({ status: "canceled", resolvedAt: at })
    .where(and(
      eq(ownershipHandovers.orgId, orgId),
      eq(ownershipHandovers.status, "pending"),
      // Either party leaving revokes the offer.
      sql`(${ownershipHandovers.fromUserId} = ${userId} OR ${ownershipHandovers.toUserId} = ${userId})`,
    )).run();
}

export interface AcceptedHandover {
  readonly organization: Organization;
  readonly previousOwner: Member;
  readonly newOwner: Member;
  readonly previousOwnerRole: Member["role"];
  readonly newOwnerRole: Member["role"];
}

export async function accept(
  handover: OwnershipHandover,
  at: IsoTimestamp,
): Promise<AcceptedHandover> {
  return getDb().transaction((tx) => {
    const orgRow = tx.select().from(organizations).where(eq(organizations.id, handover.orgId)).get();
    const fromRow = tx.select().from(members).where(and(
      eq(members.orgId, handover.orgId), eq(members.userId, handover.fromUserId), isNull(members.archivedAt),
    )).get();
    const toRow = tx.select().from(members).where(and(
      eq(members.orgId, handover.orgId), eq(members.userId, handover.toUserId), eq(members.status, "active"), isNull(members.archivedAt),
    )).get();
    const offerRow = tx.select().from(ownershipHandovers).where(and(
      eq(ownershipHandovers.id, handover.id), eq(ownershipHandovers.status, "pending"), gt(ownershipHandovers.expiresAt, at),
    )).get();
    if (!orgRow || !fromRow || !toRow || !offerRow || orgRow.ownerId !== handover.fromUserId) {
      throw new Error("Ownership handover changed while it was being accepted");
    }

    // Promote the recipient before demoting the current owner, preserving the
    // workspace's owner-role invariant throughout the transaction.
    if (toRow.role !== "owner") {
      tx.update(members).set({ role: "owner", updatedAt: at }).where(eq(members.id, toRow.id)).run();
    }
    tx.update(organizations).set({ ownerId: handover.toUserId, updatedAt: at }).where(eq(organizations.id, handover.orgId)).run();
    if (fromRow.role === "owner") {
      tx.update(members).set({ role: "admin", updatedAt: at }).where(eq(members.id, fromRow.id)).run();
    }
    tx.update(ownershipHandovers).set({ status: "accepted", resolvedAt: at })
      .where(eq(ownershipHandovers.id, handover.id)).run();

    const freshOrg = tx.select().from(organizations).where(eq(organizations.id, handover.orgId)).get()!;
    const freshFrom = tx.select().from(members).where(eq(members.id, fromRow.id)).get()!;
    const freshTo = tx.select().from(members).where(eq(members.id, toRow.id)).get()!;
    return {
      organization: toOrganization(freshOrg),
      previousOwner: toMember(freshFrom),
      newOwner: toMember(freshTo),
      previousOwnerRole: fromRow.role,
      newOwnerRole: toRow.role,
    };
  });
}

